const h = params.height;
const count = params.strands;
const baseR = h * 0.16;
const kelpMat = { preset: 'leaf', roughness: 0.72, flatShading: false, vertexColors: true };
const bladderMat = { preset: 'leaf', roughness: 0.62, flatShading: true, vertexColors: true };
const rockMat = { preset: 'stone', color: '#59615a', roughness: 0.96, flatShading: true, vertexColors: true };
const rock = api.icosphereRock(baseR * 1.3, 0.48).scale(1.2, 0.58, 1.0).translate(0, baseR * 0.42, 0);
rock.vertexColor((x, y, z) => api.mix('#394640', '#788078', 0.48 + api.noise3(x * 5, y * 5, z * 5) * 0.22));
api.add(rock, rockMat);
for (let i = 0; i < count; i++) {
  const a = (i / count) * Math.PI * 2 + (api.rng() - 0.5) * 0.32;
  const radial = baseR * (0.22 + 0.58 * api.rng());
  const sh = h * (0.68 + 0.31 * api.rng());
  const width = h * (0.034 + 0.016 * api.rng());
  const depth = width * (0.16 + 0.08 * api.rng());
  const phase = api.rng() * Math.PI * 2;
  const bends = 2.0 + api.rng() * 1.7;
  const lean = (api.rng() - 0.5) * width * 2.2;
  const levels = 11;
  const shape = [];
  for (let j = 0; j <= levels; j++) {
    const t = j / levels;
    const half = width * (1 - 0.72 * t) * (0.82 + 0.18 * Math.sin(t * Math.PI));
    const center = Math.sin(t * bends * Math.PI * 2 + phase) * width * (0.42 + 1.05 * t) + lean * t;
    shape.push([center - half, baseR * 0.42 + t * sh]);
  }
  for (let j = levels; j >= 0; j--) {
    const t = j / levels;
    const half = width * (1 - 0.72 * t) * (0.82 + 0.18 * Math.sin(t * Math.PI));
    const center = Math.sin(t * bends * Math.PI * 2 + phase) * width * (0.42 + 1.05 * t) + lean * t;
    shape.push([center + half, baseR * 0.42 + t * sh]);
  }
  const ribbon = api.extrude(shape, depth).rotate(0, a * 180 / Math.PI, 0).translate(Math.cos(a) * radial, 0, Math.sin(a) * radial);
  const strandColor = api.mix(params.color, i % 3 === 0 ? '#b2a83b' : '#244e32', 0.18 + 0.16 * api.rng());
  ribbon.vertexColor((x, y, z) => api.mix(strandColor, '#d0bd55', Math.max(0, Math.min(0.3, y / h * 0.24 + api.noise3(x * 3, y * 2, z * 3) * 0.05))));
  api.add(ribbon, kelpMat);
  const bladderCount = 2 + Math.floor(api.rng() * 3);
  for (let b = 0; b < bladderCount; b++) {
    const t = 0.48 + b * 0.13 + api.rng() * 0.07;
    if (t > 0.92) continue;
    const center = Math.sin(t * bends * Math.PI * 2 + phase) * width * (0.42 + 1.05 * t) + lean * t;
    const side = b % 2 === 0 ? 1 : -1;
    const localX = center + side * width * (0.72 - 0.35 * t);
    const rr = width * (0.42 + 0.12 * api.rng());
    const bx = Math.cos(a) * radial + Math.cos(a) * localX + Math.sin(a) * side * depth * 1.8;
    const bz = Math.sin(a) * radial + Math.sin(a) * localX - Math.cos(a) * side * depth * 1.8;
    const by = baseR * 0.42 + t * sh;
    const bladder = api.sphere(rr, 1).scale(0.8, 1.3, 0.8).translate(bx, by, bz);
    bladder.vertexColor(() => api.mix(strandColor, '#c7ad3d', 0.38));
    api.add(bladder, bladderMat);
    const tipX = bx + Math.cos(a) * side * width * 1.7;
    const tipZ = bz + Math.sin(a) * side * width * 1.7;
    const frond = api.tube([[bx, by, bz], [tipX, by + width * 0.9, tipZ]], depth * 0.42, 5);
    frond.vertexColor(() => strandColor);
    api.add(frond, kelpMat);
  }
}
api.collider({ kind: 'sphere', radius: baseR * 1.25, offset: [0, baseR * 0.42, 0] });
return api.build();
